<script setup lang="ts">
import {computed} from 'vue'
const props=withDefaults(defineProps<{value:unknown;depth?:number}>(),{depth:0})
const labels:Record<string,string>={phoneModelIds:'系统机型编号',phones:'适配机型',phoneModelId:'系统机型编号',modelName:'手机型号',brandName:'品牌',displayName:'名称',phoneModelCode:'手机编码',specification:'规格补充',beforeCents:'原单价',afterCents:'本次单价',tracking:'物流／运单',disposition:'退货处理',details:'实际开发记录',confirmed_at:'研发确认时间',originalEventId:'原办理记录',targetEventId:'被更正记录',loanId:'原借用记录',supplierItemCode:'供方货号',fileId:'文件编号',field:'变更项',name:'名称',code:'编号',productName:'产品',productCode:'产品编号',productVersion:'资料版本',specName:'规格',supplierName:'供方',supplierCode:'供方代码',person:'接收人',customerName:'客户',currency:'币种',qty:'数量',damaged:'其中损坏',location:'位置',to:'目标位置',condition:'实物状态',date:'实际日期',due:'预计归还',reason:'说明／原因',notes:'备注',result:'研发结论',record_date:'收样日期',round:'原样品轮次',no:'轮次',project:'原项目',source:'供货依据',sourceSnapshot:'来源资料',snapshot:'当时资料',customerSnapshot:'当时客户',before:'原确认',after:'本次确认',actual:'实盘好品',delta:'调整数量',retainedIds:'留样编号',lines:'商品明细',refs:'采用资料',links:'参考链接',title:'标题',url:'链接',version:'版本',mode:'结算方式',grossCents:'供方货款',feeCents:'佣金／服务费',amountCents:'实际金额',offsetCents:'佣金抵扣',priceCents:'单价',totalCents:'本单货款',unitPrice:'单价',terms:'供货约定',time:'记录时间',operator:'操作者',provenance:'来源说明',pending:'来源待核对',node:'验模确认',nodeFacts:'节点依据',fromNodeKey:'原节点',retained:'留样',good:'好品'}
const entries=computed(()=>props.value&&typeof props.value==='object'&&!Array.isArray(props.value)?Object.entries(props.value as Record<string,unknown>).filter(([k,v])=>labels[k]&&v!==null&&v!==undefined&&v!==''):[])
function scalar(key:string,v:unknown){if(key.endsWith('Cents')&&typeof v==='number')return (v/100).toFixed(2);if(typeof v==='boolean')return v?'是':'否';const names:Record<string,string>={net:'扣佣后付供方',gross:'先付货款再收佣金',good:'普通好品',retained:'确认留样',damaged:'损坏品',passed:'通过',failed:'需改进',pending:'待验证'};return names[String(v)]||String(v)}
</script>
<template><div class="partner-facts"><template v-if="Array.isArray(value)"><div v-for="(item,i) in value" :key="i" class="fact-item"><PartnerFacts v-if="typeof item==='object'" :value="item" :depth="depth+1"/><span v-else>{{item}}</span></div></template><template v-else><div v-for="[key,v] in entries" :key="key" class="fact-item"><template v-if="typeof v==='object'"><details :open="depth<1"><summary>{{labels[key]}}</summary><PartnerFacts :value="v" :depth="depth+1"/></details></template><template v-else><span class="muted">{{labels[key]}}：</span><a v-if="key==='url' && /^https?:\/\//.test(String(v))" :href="String(v)" target="_blank" rel="noopener">{{v}}</a><span v-else>{{scalar(key,v)}}</span></template></div></template></div></template>
<style scoped>.partner-facts{font-size:13px;line-height:1.8;overflow-wrap:anywhere}.fact-item{padding:3px 0}.muted{color:#7b8ba3}details{padding:5px 0 5px 12px;border-left:2px solid #e8edf5}summary{cursor:pointer;color:#48607f}</style>
